class BankAccount
{
    private decimal _balance;

    public string Owner { get; }
    public decimal Balance => _balance;

    public BankAccount(string owner, decimal openingBalance)
    {
        Owner = owner;
        _balance = openingBalance;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(amount), "Deposit must be positive.");
        }
        _balance += amount;
    }

    public bool Withdraw(decimal amount)
    {
        if (amount > _balance) return false;
        _balance -= amount;
        return true;
    }
}

Animal[] zoo = [new Dog("Rex"), new Cat("Tom"), new Animal("Generic")];

foreach (Animal animal in zoo)
{
    Console.WriteLine($"{animal.Name}: {animal.Speak()}");
}

class Animal(string name)
{
    public string Name { get; } = name;

    public virtual string Speak() => "...";
}

class Dog(string name) : Animal(name)
{
    public override string Speak() => "Woof";
}

class Cat(string name) : Animal(name)
{
    public override string Speak() => "Meow";
}

